import React from 'react'
type S={heading:string;text:string[]};type G={title:string;sections:S[]}
const guides:Record<string,G>={
"menstrual-health-calculator":{title:"Menstrual Health Score Calculator",sections:[{heading:"What this score actually measures",text:["This calculator starts at 100 and subtracts points for cycle lengths outside 21–35 days, periods outside 2–7 days, pain, very heavy flow, irregularity, PMS symptoms, mood changes and energy loss. The result is therefore a rule-based symptom and cycle-pattern score created by this site. It is not a validated clinical probability, a fertility score, or a diagnosis of a gynecologic condition.","Use the score as a structured way to notice which entered features are driving concern. A lower score can come from one severe feature, such as debilitating pain, or from several moderate features occurring together. The category should always be read alongside the individual inputs and red flags rather than treated as a stand-alone medical conclusion."]},{heading:"Cycle length and regularity",text:["Cycle length is counted from the first day of one period to the first day of the next. The calculator penalizes values below 21 days or above 35 days and separately penalizes the irregularity slider, so an unusual length and unpredictable timing can both reduce the score. Tracking several cycles is more informative than entering one unusual month after illness, travel, major stress or a medication change.","Persistently short, long or highly variable cycles can have many explanations, including anovulation, PCOS, thyroid disorders, perimenopause, changes in energy availability and other endocrine factors. The calculator can flag a pattern, but it cannot determine the cause because it does not collect laboratory results, pregnancy status, medication history or a complete clinical history."]},{heading:"Pain deserves its own interpretation",text:["Pain is heavily weighted: every point on the 0–10 pain scale removes five points from the score. A pain entry of 8 therefore has a much larger effect than a small change in mood or energy. The code also creates a red flag at pain level 8 or above because severe menstrual pain may warrant evaluation rather than normalization as an unavoidable part of menstruation.","Pain that interferes with school, work, sleep, exercise or normal activity is clinically more meaningful than the score alone can express. Endometriosis is one possible explanation for severe cyclic pain, but fibroids, adenomyosis, ovarian conditions and non-gynecologic causes can also matter. A calculator cannot distinguish among them."]},{heading:"Heavy flow and iron risk",text:["Flow heaviness is entered on a subjective 0–10 scale. Values above 5 reduce the health score, values above 7 trigger the calculator's iron-risk message, and values above 8 create a heavy-bleeding red flag. This reflects the practical link between sustained blood loss and iron deficiency, but the slider is not a measured blood-loss volume.","Useful real-world details include how often protection must be changed, flooding or leakage, passage of large clots, bleeding lasting more than a week, dizziness, breathlessness and fatigue. Ferritin and a full blood count can help evaluate iron stores and anemia when heavy bleeding is persistent. The tool suggests investigations only when its overall score falls below 50, so a concerning symptom should not be ignored merely because the total remains above that cutoff."]},{heading:"PMS, mood and energy",text:["PMS symptoms, mood changes and energy drop are modeled separately, with different point weights. This helps show that menstrual health is not only cycle timing and bleeding. Symptoms can vary across the luteal phase and early menstruation, and repeated timing relative to the cycle is often more informative than a single severity rating.","A symptom diary can record dates, bleeding, pain, sleep, mood, headaches, gastrointestinal symptoms and functional impact for two or three cycles. Severe cyclical mood symptoms require careful assessment; the calculator does not diagnose premenstrual dysphoric disorder and does not assess urgent mental-health symptoms."]},{heading:"Worked example",text:["Suppose a user enters a 28-day cycle, 5-day period, pain 3, flow 4, irregularity 1, PMS 2, mood change 2 and energy drop 2. Cycle and period length receive no deduction. Pain removes 15 points, irregularity 8, PMS 8, mood 6 and energy 4, producing a score around 59 before any other applicable flow penalty. That demonstrates why several moderate symptoms can matter even when cycle length looks textbook-normal.","Now change only pain from 3 to 8. The pain deduction rises from 15 to 40 and a severe-pain red flag appears. This one-input comparison is useful because it reveals the calculator's weighting, but it should not be interpreted as proving that pain is biologically five times more important than another symptom; those weights are model rules, not clinical effect sizes."]},{heading:"When to seek evaluation",text:["The page flags severe pain, very heavy flow, cycle length outside its range and high irregularity. In real life, pregnancy-related bleeding, fainting, severe acute pelvic pain, rapidly worsening symptoms or very heavy bleeding can require more urgent assessment than a score suggests. New symptoms after a long period of stable cycles also deserve context.","For non-urgent persistent concerns, bring a cycle record to a clinician. Depending on the pattern, evaluation may include pregnancy testing, blood count and ferritin, thyroid testing, hormone assessment or pelvic imaging. The calculator lists some of these investigations for low scores, but testing should be selected for the individual rather than ordered simply because an algorithm displayed it."]},{heading:"How to use the tool responsibly",text:["Use consistent definitions each month: count cycle days the same way, rate pain by functional impact, and keep the flow scale anchored to the same personal reference. Repeating the tool can then help visualize change after treatment, contraception changes or lifestyle changes, although normal month-to-month variation remains possible.","The best use is to organize observations and questions for a health discussion. The score cannot establish PCOS, endometriosis, anemia, infertility or hormonal health, and a high score cannot rule those conditions out. Symptoms, examination and appropriate testing remain more important than the displayed number."]},]},
'grip-strength-age-calculator':{title:'Grip Strength Age Calculator',sections:[
{heading:'What the calculator reports',text:["This tool compares measured hand-grip strength with an age- and sex-referenced value and reports a percentile, category, age-group mean and z-score. Those outputs describe how the entered measurement compares with the reference model used by the calculator. They do not literally determine a person's biological age or diagnose frailty, sarcopenia or neurological disease.",'The most useful output is relative position: a z-score near zero is close to the model mean, a positive z-score is above it and a negative z-score is below it. Percentile translates that standardized difference into an easier-to-read ranking within the reference distribution.']},
{heading:'Grip strength as a physical measure',text:['Hand-grip dynamometry captures force generated by the hand and forearm but also reflects broader neuromuscular function, body size, training and testing technique. In population studies, low grip strength is associated with functional limitations and health outcomes, which is why it is sometimes used as a simple marker of strength or frailty.','Association does not mean a grip reading is a complete health score. A climber, manual worker or strength athlete may have unusually high grip for age, while arthritis or a hand injury can lower the measurement without representing whole-body weakness.']},
{heading:'Measurement technique strongly affects the result',text:['Use a calibrated dynamometer when possible and follow a consistent protocol for posture, elbow position, handle setting, dominant versus nondominant hand, number of attempts and rest between attempts. Changing handle width alone can alter force production. Comparing measurements taken with different devices or protocols can create a false trend.','For self-tracking, record the same hand and use the same device and setup. Many formal protocols take multiple trials and use the maximum or average according to the reference standard. Match the protocol to the normative data whenever possible.']},
{heading:'Kilograms and pounds',text:['The calculator accepts kilograms or pounds and converts as needed for comparison. Be careful not to enter a pound value while the selector is set to kilograms: 95 lb is about 43 kg, so a unit mistake can more than double the interpreted strength.','Grip dynamometers may display kg-force, pounds-force or newtons. The tool is intended for the kg/lb options shown in its interface. Convert other units before entry rather than assuming similarly sized numbers are interchangeable.']},
{heading:'Age and sex reference groups',text:['Grip strength tends to vary with age and differs across reference populations. The calculator therefore asks for age and gender and shows an age-group average. A comparison is only as good as the normative model behind it; ethnicity, height, body size, occupation and sampling methods can shift population distributions.','Do not compare a 70-year-old directly with a 25-year-old using the same raw threshold when the purpose is age-referenced interpretation. Conversely, an age-adjusted percentile should not hide an important absolute weakness that affects daily function.']},
{heading:'Understanding z-score',text:['A z-score expresses the distance from the reference mean in standard-deviation units. A z-score of 0 means the entered value is at the model mean. Roughly speaking, +1 is one standard deviation above the mean and -1 is one below. The calculator rounds its output, so small changes should not be overinterpreted.','Z-scores are especially useful for tracking how unusual a value is relative to the reference distribution, but they are not disease probabilities. A low z-score is a reason to consider context, repeat measurement quality and functional symptoms.']},
{heading:'Understanding percentile',text:["Percentile answers a ranking question. A 75th-percentile result means the model places the measurement above roughly three quarters of the relevant reference distribution, not that grip strength is '75 percent healthy.' Likewise, a 10th percentile does not mean there is a 90 percent chance of disease.",'Percentiles compress the extremes: large changes in raw strength can sometimes produce smaller percentile movement near the tails. For training progress, raw force and a standardized protocol may be more informative than percentile alone.']},
{heading:'Dominant hand, pain and injury',text:['Dominant-hand strength is often greater, but the difference varies. Recent wrist, elbow, shoulder or hand pain can suppress grip. Neurological conditions, arthritis, tendon problems and surgery can also affect one side disproportionately. If one hand is unexpectedly much weaker, a single age percentile may miss that asymmetry.','Do not repeatedly squeeze maximally through acute pain simply to obtain a score. When weakness is sudden, progressive or accompanied by numbness, coordination changes or other neurological symptoms, seek appropriate clinical assessment.']},
{heading:'Training and meaningful change',text:["Grip can improve through general resistance training, loaded carries, pulling movements and grip-specific work, but training should match the person's goals and joint tolerance. Short-term day-to-day variation also occurs from fatigue, warm-up, motivation and measurement error.",'To judge progress, compare measurements under similar conditions over weeks or months. A small one-day increase is less convincing than a sustained change across repeated standardized tests.']},
{heading:'Grip strength and sarcopenia or frailty',text:["Clinical frameworks may use hand-grip cut points as one component of sarcopenia or frailty assessment. Those frameworks use specific thresholds and populations and often combine strength with muscle quantity, gait speed, chair-rise performance or other measures. This calculator's percentile/category should not be substituted automatically for those diagnostic criteria.",'Older adults with low grip plus falls, weight loss, difficulty rising from a chair or declining daily function may benefit from a broader clinical and nutritional assessment rather than focusing only on hand strength.']},
{heading:'Best way to use the result',text:['Use the calculator as a reference comparison and tracking aid. Record device, hand, protocol, raw measurement, age and date. If a result looks surprising, repeat the measurement after adequate rest and verify the unit before drawing conclusions.',"The goal is not to chase a younger 'grip age.' A useful interpretation asks whether strength is adequate for function, whether it is changing over time, and whether training, injury or health context explains the measurement."]},
]},
"metabolic-age-calculator":{title:"Metabolic Age Calculator",sections:[{heading:"How this site calculates metabolic age",text:["The implemented formula begins with chronological age, then adjusts it using BMI, resting heart rate, a self-rated fitness level and waist-to-height ratio. BMI is compared with a sex-specific reference of 27.5 for men or 27.0 for women; each BMI unit above or below that reference changes modeled age by 0.8 years. Resting heart rate changes it by 0.15 years per beat relative to 65, while each fitness-level point above or below 5 changes it by 1.2 years in the opposite direction.","The waist term uses waist circumference divided by height, despite the variable being named `whr` in the source. The model adds 30 times the difference from 0.50, then rounds and clamps the final result between ages 18 and 90. This is a custom wellness model, not a laboratory measurement of metabolic rate and not a validated biological-age algorithm."]},{heading:"Metabolic age is not BMR age",text:["Commercial devices sometimes use the phrase metabolic age by comparing estimated basal metabolic rate with population averages. This calculator does something different: it combines body-size, resting-pulse and fitness proxies. It does not calculate BMR, VO2 max, insulin sensitivity, blood lipids, blood pressure or glucose.","Because definitions vary, do not compare this result directly with a smart scale or another website unless the formulas are known to be equivalent. A five-year difference between two tools may simply reflect different models rather than a real physiological change."]},{heading:"BMI contribution",text:["BMI is useful for population screening because it relates weight to height, but it cannot distinguish fat mass from muscle mass or show fat distribution. A muscular athlete can have a high BMI with relatively low body fat, while someone with a normal BMI can still have substantial visceral fat. In this calculator, BMI affects the result mechanically even when those distinctions would change clinical interpretation.","For tracking, use a consistently measured body weight and height. Small day-to-day weight changes from hydration or glycogen should not be treated as meaningful changes in metabolic health. Longer trends and complementary measures are more informative."]},{heading:"Resting heart rate and fitness",text:["The model treats a resting heart rate above 65 as aging the score and a lower rate as reducing it. Resting pulse can reflect cardiorespiratory fitness, but it also changes with sleep, dehydration, heat, stress, illness, caffeine, medications and measurement conditions. Measure after several quiet minutes and compare readings taken under similar circumstances.","Fitness level is a 1–10 self-rating, so it is inherently subjective and has a relatively large effect on the result. Moving the slider from 5 to 8 subtracts 3.6 modeled years even if no objective fitness measurement changed. Use the same personal criteria over time or the apparent improvement may simply be a change in how you rate yourself."]},{heading:"Waist-to-height ratio",text:["Waist divided by height is a simple marker of central adiposity. The calculator uses 0.50 as its reference, so a ratio above 0.50 increases modeled age and a lower ratio decreases it. Measure waist at a consistent anatomical location, without pulling the tape tight, and use the same unit for waist and height.","The model also lists reducing waist circumference as an improvement area when the ratio exceeds 0.50. That can be directionally useful, but health risk varies with sex, ethnicity, age and other metabolic factors. A single ratio is not a diagnosis of visceral obesity or metabolic syndrome."]},{heading:"Worked example and sensitivity",text:["Consider a 40-year-old man with BMI 30, resting heart rate 75, fitness level 4, waist 100 cm and height 175 cm. Relative to the model references, BMI adds about 2 years, heart rate about 1.5 years, lower fitness about 1.2 years, and a waist-to-height ratio near 0.57 adds roughly another 2 years. The rounded metabolic age would therefore be several years above 40.","If the same user later enters BMI 27, resting heart rate 65, fitness 6 and waist 88 cm while height and age stay the same, the model can fall substantially. That comparison shows how the formula responds; it does not prove that a particular intervention literally reversed a matching number of biological years."]},{heading:"Better ways to assess metabolic health",text:["For a fuller picture, consider blood pressure, fasting glucose or HbA1c, lipid profile, physical activity, smoking status, sleep, family history and clinically appropriate measures of body composition. Cardiorespiratory fitness testing can also add information that a self-rated slider cannot capture.","Changes in these measures may matter even when the calculator's age barely moves. Conversely, a favorable modeled age should not override abnormal laboratory results or symptoms. Treat the output as a motivational summary, not a medical clearance."]},{heading:"Tracking without false precision",text:["Recalculate no more often than the inputs can meaningfully change. Waist circumference and body composition trends usually deserve weeks or months, while resting heart rate can vary daily. Record the underlying values as well as the final age so you can see what actually changed.","The useful question is not whether your body is literally '37 instead of 40.' It is whether modifiable inputs such as central adiposity, conditioning and resting pulse are moving in a healthier direction. That framing avoids giving a catchy age label more authority than the formula supports."]},]},
"svg-optimizer":{title:"SVG Optimizer",sections:[{heading:"Why SVG files become bloated",text:["Design applications often export editor metadata, verbose IDs, comments, redundant groups, unnecessary precision and repeated attributes. Browsers do not need most of that information to render a simple icon or logo.","Optimization aims to reduce transfer size and parsing work while preserving the intended appearance and behavior. The safest savings remove data that has no rendering effect."]},{heading:"Lossless cleanup first",text:["Whitespace, comments, editor namespaces, empty containers and default attributes are common lossless targets. Removing them can substantially shrink design-tool exports without changing geometry.","Start with conservative plugins and compare before and after. A small icon should be easy to inspect visually and in source control."]},{heading:"Path data and coordinate precision",text:["Path commands often contain more decimal precision than a screen can display. Rounding coordinates and simplifying commands can reduce bytes, but this is a lossy transformation because geometry changes slightly.","The safe precision depends on the artwork and viewBox. Tiny icons may tolerate fewer decimals, while technical drawings or very large scaling ranges can reveal rounding errors."]},{heading:"IDs, classes and JavaScript dependencies",text:["An optimizer may shorten or remove IDs and classes that appear unused inside the SVG. That can break external CSS, JavaScript selectors, accessibility references, gradients, masks, clip paths or animation targets.","If an SVG is interactive or styled from outside the file, configure optimization to preserve the identifiers that form its public interface."]},{heading:"viewBox and responsive scaling",text:["The viewBox defines the internal coordinate system used when the SVG scales. Removing or altering it can break responsive behavior even when the graphic still looks correct at its original dimensions.","For web icons, retaining a correct viewBox is usually more important than saving a handful of bytes. Width and height attributes can be handled separately depending on how the asset is embedded."]},{heading:"Accessibility and semantic content",text:["Optimization should not strip meaningful title, description or ARIA relationships when the SVG conveys content. Decorative SVGs can be hidden from assistive technology, while informative graphics need an accessible name or surrounding text.","Decide whether the asset is decorative before optimizing rather than treating all metadata as disposable."]},{heading:"Inline SVG, image files and sprites",text:["Inline SVG allows CSS styling and avoids a separate request but increases HTML size. External SVG files benefit from browser caching. Sprites combine many symbols but can load unused icons and create ID-management complexity.","Optimization helps all three patterns, but the best embedding choice depends on reuse, caching and styling requirements rather than file size alone."]},{heading:"Build-pipeline verification",text:["SVGO and related tools can run during builds so committed assets stay readable while production assets are optimized automatically. Pin configuration and tool versions because plugin defaults can change.","For complex graphics, add screenshot or visual-regression checks. A successful build only proves the optimizer ran; visual comparison proves the output still renders as intended."]},]},
"estate-planning-checklist-calculator":{title:"Estate Planning Checklist Calculator",sections:[{heading:"What the checklist score means",text:["This calculator is a readiness checklist, not a legal-completeness test. It looks for a will, power of attorney, healthcare directive, beneficiary review and, at higher modeled net worth, a living trust. The score is useful because it turns several commonly overlooked planning tasks into visible gaps, but a score of 100 does not prove that documents are valid, current or coordinated.","Estate planning is ultimately about control: who receives property, who can act during incapacity, who makes healthcare decisions and how assets transfer. The checklist should therefore start a review, not end one."]},{heading:"Will and guardianship",text:["A will directs probate assets and can nominate guardians for minor children. Assets with beneficiary designations, transfer-on-death registrations, joint ownership or trust ownership may pass outside the will, so the document cannot be reviewed in isolation.","A common mistake is having a signed will but leaving beneficiary forms from an old employer or prior relationship unchanged. Compare the will with retirement accounts, life insurance and account titling so the transfer mechanisms tell the same story."]},{heading:"Financial power of attorney",text:["A durable financial power of attorney authorizes a chosen agent to handle specified financial matters if needed. Without usable authority, family members may face delays or court proceedings when an owner becomes incapacitated.","The document's powers, durability, effective date and acceptance by financial institutions matter. Naming an agent is also a fiduciary decision: choose someone trustworthy, capable of recordkeeping and able to manage conflicts among family members."]},{heading:"Healthcare directive and medical decision-making",text:["Advance healthcare documents can record treatment preferences and appoint a healthcare decision-maker. Their value is practical only if the right people know they exist and can access them during an emergency.","Review names, backups, contact information and state-specific execution requirements. Medical directives should also be discussed with family rather than stored where nobody can find them."]},{heading:"Beneficiary designations and account titling",text:["Retirement plans, IRAs and life-insurance policies often transfer by beneficiary designation. Bank and brokerage accounts may use payable-on-death or transfer-on-death registrations, while jointly owned property follows its ownership form. These mechanisms can override assumptions based on a will.","Review beneficiaries after marriage, divorce, births, deaths and major account changes. Check contingent beneficiaries too; a plan with only a primary beneficiary can fail when that person dies first."]},{heading:"When a revocable trust may help",text:["The calculator gives extra weight to a living trust above a $500,000 net-worth heuristic. That threshold is a ToolTrio scoring rule, not a legal rule. A revocable trust may be useful for probate avoidance, privacy, continuity during incapacity, real estate in multiple states or more controlled administration.","A trust only governs assets actually transferred to it or otherwise directed to it. Creating a trust and never retitling intended assets is a classic implementation failure. Trust usefulness also varies by state because probate cost and procedure differ."]},{heading:"Taxes, liquidity and complexity outside the score",text:["The five-item score does not model federal or state estate tax, basis rules, business succession, special-needs planning, creditor issues, charitable planning or estate liquidity. A family business or illiquid real estate portfolio can require much more planning than a simple liquid estate of the same net worth.","Life insurance, cash reserves and ownership structure can affect whether heirs must sell assets quickly to meet taxes, debts or administration costs. Those questions deserve a separate liquidity analysis."]},{heading:"A practical annual review",text:["Once a year, confirm that documents still reflect current wishes, agents are still appropriate, beneficiaries match the plan and key people know where originals or secure copies are located. Also review after a move to another state or a major family event.","Use the calculator to identify missing categories, then maintain a simple inventory of accounts, property, insurance, debts, advisers and document locations. That inventory can be as valuable to an executor as the score itself."]},]},
"respiratory-rate-calculator":{title:"Respiratory Rate Calculator",sections:[{heading:"Measure respiratory rate correctly",text:["Respiratory rate is the number of breaths taken in one minute. Count while the person is resting and not deliberately changing their breathing. One rise and fall of the chest or abdomen counts as one breath. Counting for a full 60 seconds is useful when breathing is irregular; shorter counts multiplied upward can magnify counting error.","Recent exercise, talking, anxiety, fever, pain and stimulants can temporarily raise breathing rate. The calculator includes an 'after exercise' switch precisely because a post-exercise rate should not be interpreted with the same expectation as a quiet resting measurement."]},{heading:"Age-specific ranges in this tool",text:["The page displays different reference ranges by age: 30–60 breaths/min for infants, 18–30 for children, 12–20 for adolescents and adults, and 12–28 for older adults. These are broad educational bands. Normal ranges vary by source, clinical setting, sleep/wake state and exact pediatric age.","Age is therefore essential to the page's interpretation. A rate of 28 can be expected for an infant yet clearly elevated for a resting adult. Always verify that age was entered correctly before reacting to the category."]},{heading:"Tachypnea and bradypnea",text:["Tachypnea means breathing faster than expected for the context; bradypnea means slower. A high rate can accompany fever, pain, anxiety, lung disease, metabolic acidosis, infection or cardiovascular problems. A low rate can occur during sleep or athletic conditioning but can also be associated with sedating drugs, neurological problems or severe illness.","The calculator can label a rate but cannot identify the cause. Work of breathing, oxygen saturation, mental status, chest pain and the overall clinical picture can matter more than the exact number."]},{heading:"Post-exercise breathing",text:["Exercise increases ventilation to meet metabolic demand and remove carbon dioxide. A temporarily elevated rate after training can therefore be normal. Recovery speed depends on exercise intensity, fitness, temperature and health. The site's post-exercise setting changes how it describes elevation, but it does not know how hard the exercise was or how many minutes have passed.","For a meaningful resting baseline, wait until breathing has settled. If breathlessness is disproportionate to the activity, persists unexpectedly or is accompanied by concerning symptoms, a normal-looking calculator category should not be used to dismiss it."]},{heading:"Altitude context",text:["The page accepts altitude and returns an altitude-effect message. At higher elevation, lower oxygen pressure stimulates ventilation, particularly during initial acclimatization. People may breathe faster at rest or during exertion even without lung disease.","Altitude effects depend on elevation, acclimatization and individual susceptibility. The calculator's altitude information is contextual rather than a precise correction of respiratory rate. New severe headache, confusion, marked breathlessness at rest or other symptoms at altitude require attention beyond a breathing-rate calculation."]},{heading:"Minute ventilation estimate",text:["The result includes minute ventilation and oxygen-per-minute outputs. Minute ventilation normally means tidal volume multiplied by respiratory rate. Because this page does not ask the user to measure tidal volume directly, any derived ventilation value is an estimate based on assumptions inside the calculation rather than a spirometry measurement.","Two people breathing 16 times per minute can have very different ventilation if one takes shallow breaths and the other takes deep breaths. Do not use the displayed ventilation estimate to diagnose hypoventilation or hyperventilation."]},{heading:"Worked interpretation",text:["A resting 35-year-old entering 16 breaths per minute is within the page's adult 12–20 range. Changing only the rate to 26 moves the same adult into an elevated range, whereas entering an infant age changes the expected range substantially. This demonstrates why the raw number and age category must be considered together.","If the 26-breath rate was measured immediately after climbing stairs, switching on the post-exercise context changes interpretation. Repeating the measurement after recovery gives a more useful resting comparison."]},{heading:"Red flags and trend monitoring",text:["A sustained change from a person's usual respiratory rate can be clinically useful, even before the value becomes extreme. In healthcare, respiratory rate is often tracked with other vital signs because worsening breathing can signal deterioration. Record conditions consistently if monitoring over time.","Seek appropriate medical assessment for severe breathing difficulty, blue or gray coloration, confusion, chest pain, fainting or rapidly worsening symptoms. The calculator is an educational reference for rate and context; it is not a triage system and cannot determine whether breathing is adequate from rate alone."]},]},
'gratuity-calculator':{title:'Gratuity Calculator',sections:[
{heading:'What gratuity means in this calculator',text:["This calculator estimates an Indian employee's gratuity using last drawn monthly salary, completed service and whether the employment is treated as covered or not covered by the Payment of Gratuity Act framework implemented by the tool. Gratuity is an end-of-service benefit; it is not the same as provident fund, pension, leave encashment or severance negotiated separately.",'For covered employees, the familiar statutory structure uses 15 days of eligible wages for each completed year of service, with 26 working days used as the monthly divisor. The page identifies eligible salary as basic salary plus dearness allowance. Other components of gross pay should not be inserted unless they are legally part of the applicable gratuity wage definition.']},
{heading:'Covered-employee formula',text:['For an employee covered by the Act, the standard calculation is commonly expressed as gratuity = last drawn eligible monthly salary × 15/26 × years of service counted for gratuity. The 15/26 factor converts monthly salary into fifteen days of wages on the statutory 26-day basis. This makes salary and credited service the two dominant numerical drivers.','At a last drawn basic-plus-DA salary of 50,000 and ten credited years, the formula gives roughly 50,000 × 15/26 × 10, or about 288,462 before applying tax rules or statutory limits. Doubling eligible salary approximately doubles this formula amount; adding a credited year adds another fifteen-days-of-wages slice.']},
{heading:'Service rounding can matter',text:['Gratuity service is not always identical to the decimal number of years between joining and leaving. The page notes the common rule that a final period above six months is rounded to the next completed year for covered employment, while a shorter residual period is ignored. Thus five years and seven months may be credited differently from five years and five months.','The current input is whole years, so it cannot itself capture every joining date, termination date, seasonal establishment rule or dispute about continuous service. When the final partial year matters, calculate credited service from actual employment dates under the rule applicable to the employee rather than simply rounding a decimal duration mechanically.']},
{heading:'Eligibility and the five-year rule',text:["Five years of continuous service is a common eligibility threshold, which is why the calculator's service input begins at five years. However, gratuity law contains important circumstances and judicial interpretations, and death or disablement can be treated differently from ordinary resignation. The calculator should therefore be used for an ordinary planning estimate rather than as a legal eligibility determination.",'Continuous service can also involve questions around authorized leave, sickness, layoff, strike, lockout and other interruptions. If eligibility is disputed, the employment record and applicable statutory provisions matter more than the calculator output.']},
{heading:'Covered versus uncovered treatment',text:["The calculator asks whether the employee is covered because gratuity calculations can differ outside the statutory covered formula. An employer's policy, award, contract or scheme may specify another basis. Do not switch the selector merely to obtain a larger result; choose the status that corresponds to the actual employment arrangement.","For an uncovered employee, verify the employer's gratuity scheme and the tax rule that applies to the payment. Salary definition, days-per-month convention and exemption computation may differ. A generic calculator cannot infer those facts from salary and service alone."]},
{heading:'Tax-free amount and taxable gratuity',text:['The result cards separate estimated gratuity, tax-free amount and taxable gratuity. That distinction is essential because receiving gratuity and qualifying for an income-tax exemption are separate questions. Exemption treatment can depend on whether the employee is a government employee, whether the employer is covered by the Gratuity Act, the formula-based amount and the statutory lifetime ceiling applicable at the time.','Do not assume the displayed tax-free amount means no filing or documentation is required. Previous gratuity exemptions from earlier employers may affect a lifetime ceiling, and tax law can change. Confirm the current limit and the employee category for the year of receipt before relying on the tax estimate.']},
{heading:'Why last drawn salary matters',text:['The statutory formula is sensitive to the eligible salary near termination. A promotion or dearness-allowance revision shortly before leaving can therefore affect gratuity materially, while allowances outside the legal wage definition may not. Use the salary figure actually recognized for gratuity, not take-home pay and not total cost to company.',"When comparing job offers, gratuity shown inside CTC is not equivalent to cash salary received each month. It is a contingent employment benefit whose realization depends on service and eligibility. Treating the employer's annual gratuity provision as immediately spendable compensation overstates current cash income."]},
{heading:'Per-year gratuity as an interpretation aid',text:["The calculator also displays a per-year earned figure. This is useful for understanding the formula's scale: under the covered formula each credited year is worth roughly 15/26 of the eligible monthly salary at the last-drawn salary basis. It should not be interpreted as an amount that is separately deposited into an employee account every year.","Because the final salary can change over a career, the ultimate gratuity may not equal the sum of annual estimates calculated using each year's historical salary. The statutory formula's last-drawn-salary feature can make later pay growth affect the value attributed to earlier credited years."]},
{heading:'Worked scenario and sensitivity',text:['Consider an employee with eligible salary of 80,000 and twelve credited years under the covered formula. The gross formula estimate is about 80,000 × 15/26 × 12 = 553,846. If credited service becomes thirteen years, the estimate rises by about 46,154. If eligible salary rises to 90,000, all credited years are revalued at the higher salary in this simplified calculation.','This sensitivity is useful for retirement and job-change planning, but it should not drive a decision in isolation. Waiting solely to cross a service boundary can have an economic benefit, yet salary differences, career opportunities, notice obligations and other benefits may be much larger.']},
{heading:'Situations requiring extra care',text:['Maternity leave, fixed-term employment, death, disablement, seasonal establishments, transfers between entities, breaks in service and employer restructurings can create questions not represented by three calculator inputs. Likewise, organizations may provide a contractual gratuity benefit that is more generous than the statutory minimum.',"If the employer's HR statement differs from the estimate, compare salary definition, credited service, coverage status, rounding and any ceiling before assuming either figure is wrong. Those five items explain many differences."]},
{heading:'Use current law, not a timeless number',text:["Gratuity is governed by law and tax rules that can be amended. A ceiling or exemption amount embedded in software can become stale even when the core formula remains familiar. For a payment expected years in the future, treat today's tax-free estimate as provisional and recalculate near the actual separation date.",'For a high-value payment, confirm the current Payment of Gratuity Act provisions, employer policy and Income-tax treatment from authoritative sources or a qualified professional. The calculator is best used to understand the mechanics and approximate scale, not to replace a formal settlement statement.']},
]},
"yaml-formatter":{title:"YAML Formatter",sections:[{heading:"What a YAML formatter should preserve",text:["Formatting YAML is not merely inserting spaces. YAML represents mappings, sequences, scalars, anchors, aliases and block strings, and a formatter must preserve the parsed data structure while producing consistent indentation and quoting.","For configuration files, semantic preservation is the acceptance test. After formatting, validate the result and compare parsed data rather than assuming visually cleaner output is equivalent."]},{heading:"Indentation is structure",text:["YAML uses indentation to express nesting. Tabs are not valid indentation, and moving a line by even one level can attach a key to a different mapping or sequence item.","Use a consistent indentation width and let a parser detect malformed structure. Manual alignment with extra spaces can look attractive while making future edits fragile."]},{heading:"Scalars, quoting and surprising types",text:["Plain scalars can be interpreted as strings, numbers, booleans, nulls, dates or other schema-dependent types. YAML 1.1 and 1.2 differ on some values, which is why strings such as yes, no or on can surprise users in older parsers.","Quote values when preserving their string identity matters, especially IDs with leading zeros, version numbers, date-like strings and values consumed by systems with strict schemas."]},{heading:"Block scalars for multiline text",text:["The literal style | preserves line breaks, while folded style > generally folds ordinary line breaks into spaces. Chomping indicators such as |- and |+ control trailing newlines.","These details matter for shell scripts, certificates, SQL and embedded configuration. A formatter should not casually convert between block styles because whitespace may be meaningful to the downstream application."]},{heading:"Sequences and mappings",text:["Dash-prefixed sequence items can contain scalars or nested mappings. Flow-style syntax such as [a, b] and {key: value} is also valid YAML and can be useful for compact data.","When reformatting, choose readability over aggressive compaction. Deeply nested Kubernetes or CI configuration is usually easier to review in block style."]},{heading:"Anchors, aliases and merge keys",text:["Anchors define reusable nodes and aliases reference them. Merge-key patterns are common in Docker Compose and other configuration ecosystems, although support can depend on parser and schema.","Conversion to JSON may expand or lose YAML-specific constructs and always loses comments. Keep the original YAML when comments and authoring structure are part of the configuration's value."]},{heading:"Syntax validity versus application validity",text:["A parser can confirm valid YAML while Kubernetes, Docker Compose, GitHub Actions or another application still rejects the file. Those systems impose schemas, required keys and value constraints beyond YAML syntax.","After formatting, run the domain validator: for example, a dry-run or configuration command supplied by the target platform. Formatting should be one stage in validation, not the final guarantee."]},{heading:"Safe workflow for production configuration",text:["Keep configuration in version control, format a copy or review the diff, validate syntax, then run application-specific validation before deployment. Pay special attention to changed indentation, quoted values, anchors and multiline strings.","Do not paste secrets into third-party tools unless you understand how data is handled. Redact tokens, passwords, private keys and credentials when formatting sensitive configuration."]},]},
"emf-exposure-calculator":{title:"EMF Exposure Score Calculator",sections:[{heading:"What the exposure score means",text:["This page creates a relative exposure score from Wi-Fi hours, mobile-call time, router distance, sleeping near a phone, wired-earphone use, smart-meter distance and microwave use. It is an educational scoring model, not a measurement in volts per meter, watts per square meter, specific absorption rate, or percentage of a regulatory exposure limit.","The code explicitly notes that current evidence does not confirm health harm at typical consumer radiofrequency levels. A high score therefore means high exposure relative to this site's chosen behaviors and weights; it does not mean a high probability of cancer, infertility, neurological disease or another health outcome."]},{heading:"How the phone component is weighted",text:["Phone-call time receives a stepped score: the model assigns more points above one and two hours per day. If wired earphones are used, that phone component is multiplied by 0.3. The logic is attempting to represent the fact that distance from an RF source strongly changes local exposure, but the 70% reduction is a model assumption rather than a measurement of a specific handset and network condition.","Actual phone RF output varies with signal quality, device design, network technology, data activity and how the phone is held. Speakerphone or a wired headset can increase separation from the head, but this calculator cannot estimate a person's absorbed dose."]},{heading:"Router distance and Wi-Fi time",text:["Wi-Fi points rise with hours of use and are multiplied by a distance category: less than one meter receives the largest factor, one to three meters an intermediate factor, and more than three meters a smaller factor. This is a coarse representation of exposure decreasing with distance.","Real indoor fields are more complicated than a simple distance rule because walls, reflections, antenna orientation, transmit power and traffic matter. 'Wi-Fi hours' also does not mean the router transmits continuously at maximum power for that entire period. Treat the score as behavioral comparison, not RF dosimetry."]},{heading:"Sleeping near a phone and smart meters",text:["Sleeping near a phone adds three model points regardless of whether the phone is idle, transmitting, in airplane mode or connected to a weak signal. Smart-meter proximity adds points below three meters. These simple yes/no and distance bands make the tool easy to use but omit the duty cycle and power characteristics that determine actual fields.","If reducing unnecessary exposure is personally desirable, distance is a low-cost control: do not keep transmitting devices against the body when they are not needed, and place devices farther from the bed when practical. These steps should be framed as exposure reduction, not as proven disease prevention."]},{heading:"Microwave ovens and leakage",text:["The calculator adds a small amount based on microwave uses per day. Properly functioning microwave ovens are shielded and subject to leakage limits; standing farther away further reduces exposure. Number of uses alone cannot determine leakage from a particular appliance.","A damaged door, latch or seal is a maintenance issue rather than something this score can evaluate. Do not defeat safety interlocks. If an appliance is visibly damaged or suspected to malfunction, follow manufacturer or qualified-service guidance rather than relying on the calculator."]},{heading:"Worked score comparison",text:["Imagine 10 hours of Wi-Fi, 1.5 hours of calls, a router two meters away, sleeping beside the phone, no wired headset, a smart meter five meters away and two microwave uses. Phone, Wi-Fi and sleep components dominate the result. Moving the phone away at night and using wired earphones can materially lower the site's score even though Wi-Fi hours stay unchanged.","That comparison is exactly what the tool is good at: showing which entered behavior carries the most weight in its formula. It cannot tell you how many microwatts per square centimeter were reduced or whether the change produces a measurable health benefit."]},{heading:"Ionizing versus non-ionizing radiation",text:["Radiofrequency fields from phones and Wi-Fi are non-ionizing. They do not carry enough photon energy to ionize atoms in the same way as X-rays or gamma rays. Grouping all 'radiation' together can create misleading risk comparisons.","Established RF safety standards focus heavily on limits designed to prevent excessive tissue heating and other known effects. Scientific research continues to evaluate long-term exposures, but uncertainty should not be converted into a made-up individual disease percentage."]},{heading:"Responsible use of the calculator",text:["Use the score to compare your own scenarios with the same inputs and assumptions. If you change router distance, headset use or sleeping location, note which variable changed. Avoid interpreting small score differences as biologically meaningful because the weights are simplified.","For occupational RF sources, implanted medical devices, unusual high-power transmitters or compliance questions, this consumer score is not appropriate. Those situations require device-specific instructions, workplace safety procedures or actual field measurements and applicable exposure standards."]},]},
"fha-vs-conventional-calculator":{title:"FHA vs Conventional Mortgage Calculator",sections:[{heading:"What the comparison is really measuring",text:["This calculator compares modeled FHA and conventional mortgage costs using purchase price, down payment, credit profile and built-in rate and mortgage-insurance assumptions. It is a scenario comparison, not a live lender quote or underwriting decision.","The winning option can change with interest rate, upfront financing, monthly mortgage insurance, how long the loan is kept and whether conventional PMI eventually disappears. Compare the same holding period rather than only the first monthly payment."]},{heading:"FHA down payment and upfront MIP",text:["FHA financing can permit relatively low down payments for eligible borrowers, but the loan generally includes an upfront mortgage insurance premium as well as annual MIP paid monthly. Financing the upfront premium increases the starting loan balance and therefore interest paid over time.","A lower cash requirement can be valuable when preserving emergency reserves matters. It should not be confused with a lower total cost."]},{heading:"Conventional PMI",text:["Conventional loans with higher loan-to-value ratios may require private mortgage insurance. PMI pricing depends on credit score, LTV and insurer/lender factors, so a single calculator assumption cannot reproduce every quote.","Unlike a simple model that keeps PMI forever, many conventional loans can reach borrower-requested cancellation or automatic termination conditions. If you expect to hold the mortgage long enough, model a second scenario in which PMI ends."]},{heading:"Credit score changes the comparison",text:["FHA pricing can be more forgiving for some lower-credit borrowers, while strong-credit conventional borrowers may receive better rate and PMI terms. The page's credit bands are broad assumptions rather than lender-specific risk pricing.","A small rate difference compounds across a large balance. Obtain Loan Estimates on the same day because comparing an old FHA quote with a new conventional quote can make the product difference look larger than it is."]},{heading:"Loan limits and property eligibility",text:["FHA loan limits vary by county and property type. A purchase above the applicable limit may require a larger down payment or a different loan structure. Conventional conforming limits also matter for agency-eligible pricing.","FHA additionally has property and appraisal requirements that can affect some transactions. The calculator does not evaluate property condition or loan eligibility."]},{heading:"Monthly payment is not the whole housing cost",text:["Principal, interest and mortgage insurance are only part of ownership cost. Property tax, homeowners insurance, HOA dues, maintenance and utilities can dominate affordability even when one mortgage product looks cheaper.","Use total housing cost when checking debt-to-income and emergency reserves. A loan that qualifies on paper can still be uncomfortable if non-mortgage housing expenses are ignored."]},{heading:"Worked comparison logic",text:["Suppose FHA requires less cash today but carries both financed upfront MIP and ongoing monthly MIP, while conventional requires more cash but has cancellable PMI. FHA may look better for a short holding period or constrained down payment; conventional may overtake it after PMI cancellation and principal reduction.","Change one assumption at a time—down payment, credit band, holding period or rate—to see what drives the crossover. That is more informative than declaring one loan type universally cheaper."]},{heading:"Use real Loan Estimates before deciding",text:["Before closing, compare lender Loan Estimates for rate, APR, points, lender credits, mortgage insurance, origination charges and cash to close. Also check whether one quote assumes discount points that the other does not.","The calculator is best used to understand the mechanics and prepare questions. Eligibility, underwriting and actual pricing come from the lender and applicable program rules."]},]},
"business-loan-calculator":{title:"Business Loan Calculator",sections:[{heading:"What the payment estimate represents",text:["A business term-loan payment is driven by amount borrowed, interest rate, repayment term and payment frequency. The calculator can show debt-service mechanics, but lender underwriting also depends on business cash flow, collateral, owner guarantees, credit history and industry risk.","Treat the payment as an obligation the business must support through weak as well as strong months. Approval capacity and prudent borrowing capacity are not always the same number."]},{heading:"Amortization and total interest",text:["In a fully amortizing loan, each payment covers interest on the outstanding balance plus principal. Longer terms lower required monthly debt service but increase the time interest accrues. Shorter terms demand more cash each month while reducing total financing cost.","Match term to the useful life of what is being financed. Using long-lived debt for a short-lived marketing campaign can leave payments after the benefit has disappeared."]},{heading:"DSCR and cash-flow coverage",text:["Debt-service coverage ratio compares cash flow available for debt service with required principal and interest payments. A DSCR of 1.25 means $1.25 of available cash flow for each $1.00 of modeled debt service.","Lenders define cash flow differently, so do not assume one EBITDA figure automatically matches underwriting. Normalize owner compensation, one-time expenses and existing debt consistently with the lender's method."]},{heading:"SBA versus conventional and online financing",text:["SBA-guaranteed loans can offer longer terms or access for qualifying businesses but involve program rules, documentation and fees. Conventional bank loans may be faster for strong borrowers, while online lenders often trade speed and flexibility for higher pricing.","Compare effective cost, collateral requirements, guarantees, prepayment terms and funding speed—not just the advertised rate."]},{heading:"Fees and effective borrowing cost",text:["Origination fees, packaging charges, guarantee fees and closing costs reduce the net cash the business receives or increase the amount financed. A loan with a lower note rate can therefore cost more than a higher-rate alternative with fewer fees.","If the calculator does not incorporate every fee into APR, create a cash-flow comparison using net proceeds and all scheduled payments."]},{heading:"Variable rates and refinancing risk",text:["Some business loans and lines of credit use floating rates. If the benchmark rises, debt service can increase even though principal is unchanged. Stress-test a higher rate before borrowing near the limit of available cash flow.","Refinancing is not guaranteed. Credit conditions, business performance or collateral values may be worse when the balloon or maturity date arrives."]},{heading:"Worked capacity example",text:["Suppose a business expects $125,000 of annual cash flow available for debt service and wants a 1.25 coverage cushion. That supports about $100,000 of annual debt service before considering other lender adjustments. Existing loans must be included before assigning all of that capacity to a new loan.","Then compare the proposed loan's annual payments with the remaining capacity. This turns the calculator from a payment quote into a cash-flow test."]},{heading:"Borrow for return, not just availability",text:["The economic question is whether the financed asset or project can generate enough incremental cash flow and strategic value to justify debt cost and risk. Equipment that removes a production bottleneck can be analyzed differently from borrowing to cover recurring operating losses.","Build a repayment plan that still works if revenue is delayed or margins compress. Maintaining liquidity after closing is often more valuable than maximizing the approved loan amount."]},]},
"spo2-risk-calculator":{title:"SpO₂ Oxygen Saturation Risk Calculator",sections:[{heading:"What SpO₂ represents",text:["Pulse oximetry estimates the percentage of hemoglobin binding sites carrying oxygen in arterial blood. The page accepts a measured SpO₂ value and classifies it after a simple altitude adjustment. SpO₂ is not the same as arterial oxygen partial pressure, oxygen delivery to tissues, ventilation or a diagnosis of respiratory failure.","A single reading should be interpreted with symptoms and measurement quality. Trends can be more useful than an isolated value, especially when the reading is close to a threshold. Someone who is severely short of breath or otherwise acutely unwell should not delay care because a consumer oximeter displays a reassuring number."]},{heading:"How this calculator classifies readings",text:["After adjustment, the code labels 98% or more optimal, 95–97% normal, 92–94% borderline low, 88–91% low/hypoxemia and below 88% critical. It returns an emergency threshold of 88%. These are simplified site rules and are not a substitute for individualized targets set by a clinician.","The page also changes its displayed 'normal range' to 92–96% when the user selects underlying lung disease and changes a supplemental-oxygen threshold field from 90 to 88. Chronic lung disease is diverse; prescribed oxygen targets can differ, so users with COPD or another condition should follow their care plan rather than a generic range."]},{heading:"Altitude adjustment in the code",text:["The calculator adds altitude divided by 3,000 to the entered saturation before classifying it. At 6,000 feet, for example, it adds two percentage points. This is a heuristic intended to acknowledge that oxygen saturation can be lower at altitude; it is not a physiological correction formula that converts a mountain reading into a true sea-level equivalent.","Acclimatization, altitude reached, rate of ascent, sleep, illness and individual physiology all influence saturation. At high altitude, symptoms of altitude illness matter independently of the adjusted number."]},{heading:"How to get a better pulse-ox reading",text:["Warm the hand, rest quietly, remove barriers such as opaque nail products when they interfere, keep the finger still and wait for a stable reading. Poor peripheral circulation, motion and device fit can cause erratic values. Compare with your usual baseline when possible.","Pulse oximeters have measurement error, especially at lower saturations. Device performance can also vary across skin pigmentation and clinical conditions. Repeating an unexpected reading and checking the person rather than only the device is important."]},{heading:"Symptoms change urgency",text:["The calculator allows symptoms to be selected and lists them as concerns, but the numerical classification itself is driven by saturation and altitude. Severe breathlessness, blue or gray lips, confusion, chest pain, fainting or rapidly worsening illness can be urgent even if the displayed percentage has not crossed the site's critical threshold.","Conversely, a stable person with a chronic respiratory condition may have a clinician-defined baseline lower than a healthy person's. Context is why the tool should support, not replace, medical assessment."]},{heading:"Worked examples",text:["At sea level, an entered SpO₂ of 97% remains 97% after adjustment and falls in the site's normal category. At 6,000 feet, a measured 93% becomes 95% under the calculator's heuristic and may therefore display normal. That does not mean the person's blood literally contains the same oxygen as a sea-level 95% reading; it only shows how this model changes classification for altitude.","A reading of 87% at sea level falls below the site's emergency threshold. Rechecking technique is sensible if the person appears well and the reading is surprising, but persistent very low saturation or serious symptoms warrants prompt medical attention rather than repeated calculator experiments."]},{heading:"SpO₂ cannot tell you everything",text:["Normal saturation does not exclude asthma, pulmonary embolism, early pneumonia, anemia, carbon-monoxide exposure or other serious conditions. Carbon monoxide is particularly important because conventional pulse oximetry can be misleading. The calculator also does not use respiratory rate, heart rate, temperature or blood-gas measurements.","Likewise, a low reading does not reveal the cause. Lung disease, heart disease, hypoventilation, altitude and measurement artifact can all contribute. Diagnosis requires clinical context."]},{heading:"Use trends and personal targets",text:["If monitoring during an illness or chronic condition, record time, saturation, symptoms, oxygen use and activity state. Compare resting readings with resting readings rather than mixing them with values taken immediately after exertion. Follow any threshold provided by your clinician.","This tool is most useful for understanding categories and prompting attention to a concerning reading. It should not be used to start, stop or change supplemental oxygen on your own, and its altitude-adjusted value should not be presented as a measured saturation."]},]},
"72t-sepp-calculator":{title:"72(t) SEPP Calculator",sections:[{heading:"What a 72(t) SEPP is",text:["Section 72(t) substantially equal periodic payments can provide an exception to the 10% additional tax on certain early retirement-account distributions when a qualifying payment series is established and maintained. This is a specialized tax strategy, not simply a withdrawal-rate calculator.","The calculator compares simplified payment estimates, but the legal SEPP depends on IRS-permitted methods, account valuation, interest-rate limits, life-expectancy or mortality assumptions and strict modification rules."]},{heading:"The three payment approaches",text:["IRS guidance recognizes required-minimum-distribution, fixed-amortization and fixed-annuitization approaches. The RMD method recalculates payments as account value and life expectancy change, so payments can vary. Fixed amortization generally creates a level annual amount from a balance, permitted rate and life-expectancy factor. Fixed annuitization uses an annuity factor based on prescribed mortality information and an allowed rate.","These methods can produce materially different cash flow. A larger initial payment is not automatically better because the account must support the distribution series through market cycles."]},{heading:"Why the calculator is only an estimator",text:["This site's shortcut life-expectancy logic is educational and is not an IRS life-expectancy table. Do not use a displayed amount to establish an actual SEPP without reproducing the calculation under current IRS guidance.","The valuation date matters as well. A correct formula applied to the wrong account balance can invalidate planning assumptions, so document the balance source and calculation date."]},{heading:"Interest-rate limits",text:["Fixed amortization and annuitization methods are constrained by IRS interest-rate rules. Current guidance generally permits a rate no greater than the greater of 5% or 120% of the federal mid-term rate for either of the two months immediately preceding the first distribution month.","Using a higher assumed rate generally increases the modeled fixed payment, which makes rate selection consequential. Verify the applicable published rate for the intended start month rather than treating the calculator's entry as freely selectable."]},{heading:"The five-year and age 59½ rule",text:["A SEPP generally must continue until the later of five years after the first payment or reaching age 59½. For someone starting at 50, the age test can dominate; for someone starting near 58, the five-year test can extend the commitment well past 59½.","This timing rule is why SEPPs are difficult to reverse. Before starting, model living expenses, other income and emergency reserves for the entire required period."]},{heading:"Modification and recapture risk",text:["Improperly changing the payment series can trigger recapture of the additional tax that the exception previously avoided, plus interest. Extra withdrawals, transfers, contributions or calculation changes can therefore have consequences beyond one year's tax return.","Keep the SEPP account operationally separate from money you may need for unrelated withdrawals. Good records should show the original balance, method, rate, table, annual payment and every distribution."]},{heading:"Market risk and account sustainability",text:["A fixed dollar payment can become a rising percentage of the account after a market decline. That sequence risk matters because the tax rule may require continuing the series even when selling assets is unattractive.","Run portfolio stress cases outside the tax calculation: weak early returns, high inflation and several years of withdrawals. A tax-compliant payment can still be financially unsustainable."]},{heading:"When professional review matters",text:["SEPP planning combines tax law and retirement cash-flow design. Verify the current IRS notice, permitted tables, interest rate, account eligibility, payment frequency and modification rules with a qualified professional before implementation.","Use this calculator to understand method sensitivity and ask better questions. It should not be the sole record supporting an actual 72(t) election."]},]},
'pcos-risk-calculator':{title:'PCOS Risk Calculator',sections:[
{heading:'What this PCOS score can and cannot tell you',text:['This calculator combines menstrual-cycle features, acne, hirsutism, BMI, fasting insulin, family history, hair loss and reported ovarian cysts into an internal PCOS risk score. It is a screening-style educational model, not the Rotterdam criteria applied by a clinician and not a percentage probability that PCOS is present.','PCOS is a syndrome diagnosed from a pattern of ovulatory dysfunction, hyperandrogenism and ovarian morphology after considering other causes. No single symptom, insulin value or ultrasound finding proves PCOS, and a calculator cannot perform the history, examination and laboratory exclusion needed for diagnosis.']},
{heading:'Cycle length and irregularity',text:['Long, infrequent or unpredictable cycles can reflect oligo-ovulation or anovulation, which is a major PCOS feature. The calculator therefore asks both average cycle length and irregularity. Averages can hide variation, so a person alternating between short and very long cycles may have a normal-looking average despite meaningful irregularity.','Cycle changes can also occur with pregnancy, breastfeeding, perimenopause, thyroid disease, high prolactin, major weight change, low energy availability, intense training, stress and some medications. Persistent irregularity deserves evaluation rather than automatic attribution to PCOS.']},
{heading:'Acne, hirsutism and hair loss',text:['Acne, increased terminal hair growth in androgen-sensitive areas and scalp hair thinning can be clinical signs of androgen excess. Hirsutism is more specific than ordinary body-hair variation, while acne alone is common and has many causes. The calculator weights these features as risk signals rather than treating them as diagnoses.','Clinical assessment may use a standardized hirsutism score and, when appropriate, biochemical androgen testing. Ethnicity, hair-removal practices, medications and laboratory methods affect interpretation. Sudden severe virilization or rapidly progressive symptoms require prompt medical assessment because causes other than typical PCOS must be considered.']},
{heading:'BMI is a modifier, not a requirement',text:['PCOS occurs across the body-size spectrum. A higher BMI can be associated with insulin resistance and may worsen some metabolic and reproductive features, but a person does not need overweight or obesity to have PCOS. Conversely, a high BMI does not establish the diagnosis.','Use the BMI input as one contextual factor. If the score is low mainly because BMI is low, do not dismiss persistent irregular cycles or hyperandrogenic symptoms. Lean PCOS is a recognized presentation.']},
{heading:'Fasting insulin and insulin resistance',text:["The tool includes fasting insulin because insulin resistance and compensatory hyperinsulinemia are common in PCOS. However, fasting insulin lacks a single universally accepted diagnostic cutoff for PCOS and varies by assay and physiology. The calculator's insulin-resistance label should therefore be read as a model interpretation, not a laboratory diagnosis.",'Clinical metabolic evaluation may instead emphasize glucose status, an oral glucose tolerance test in selected patients, lipids, blood pressure and other risk factors. Normal fasting insulin does not exclude PCOS, and an elevated value can occur for reasons unrelated to PCOS.']},
{heading:'Family history changes prior risk',text:['PCOS and related metabolic traits cluster in families, so family history can raise suspicion when compatible symptoms are present. It is still not deterministic: relatives can have different phenotypes, and many people with PCOS have no known diagnosed family member.','When answering the family-history input, use known PCOS diagnoses where possible rather than assuming any infertility or diabetes in a relative was caused by PCOS.']},
{heading:'Ovarian cysts are often misunderstood',text:['The name polycystic ovary syndrome is confusing. The ovarian morphology associated with PCOS refers to a characteristic follicle pattern and/or ovarian volume on ultrasound, not necessarily the large painful ovarian cysts people commonly imagine. A person can meet diagnostic criteria without polycystic ovarian morphology, depending on the other features and the diagnostic framework used.',"Likewise, an incidental ovarian cyst does not prove PCOS. Ultrasound interpretation depends on age, equipment, hormonal contraception and clinical context. The calculator's cyst input is therefore only one signal."]},
{heading:'Other conditions must be considered',text:['PCOS-like symptoms can overlap with thyroid disorders, hyperprolactinemia, nonclassic congenital adrenal hyperplasia, Cushing syndrome, androgen-secreting tumors and medication effects. Pregnancy and normal life-stage changes can also alter cycles. A real diagnostic process considers these alternatives when indicated.','This is why an elevated calculator score should lead to appropriate evaluation rather than self-treatment based on the number alone. The higher the symptom burden or the more rapid the onset, the more important that distinction becomes.']},
{heading:'Metabolic and long-term context',text:['PCOS can be associated with impaired glucose regulation, type 2 diabetes risk, dyslipidemia, sleep apnea and endometrial effects from prolonged anovulation. Those risks are not captured fully by the displayed PCOS score. Blood pressure, glucose, lipids, sleep symptoms and cycle frequency can therefore matter even when the immediate concern is acne or fertility.','Repeatedly going long periods without menstrual bleeding can have implications for endometrial protection. A clinician can advise on cycle management based on pregnancy goals and individual risk.']},
{heading:'Fertility and treatment are individualized',text:["Ovulatory dysfunction can make conception less predictable, but PCOS does not mean infertility is inevitable. Treatment depends on the person's goals: cycle regulation, androgen symptoms, metabolic health and conception may call for different approaches. Lifestyle changes, medications and fertility treatments should not be selected from a calculator score.",'If pregnancy is desired, document cycle timing and seek individualized guidance when appropriate. If pregnancy is not desired, irregular cycles should not be assumed to provide contraception because ovulation can still occur unpredictably.']},
{heading:'How to use this tool responsibly',text:['Use the result to organize symptoms and identify which inputs are driving the score. A cycle diary, medication list, family history and prior laboratory or ultrasound reports can make a clinical discussion more productive. Repeat the calculator only when the underlying pattern has genuinely changed rather than checking it repeatedly for reassurance.','Seek prompt medical care for severe pelvic pain, very heavy bleeding, pregnancy concerns, rapidly developing virilization or other acute symptoms. For routine PCOS questions, the calculator is an educational starting point; diagnosis and treatment require clinical context.']},
]},
"diet-quality-score-calculator":{title:"Diet Quality Score Calculator",sections:[{heading:"What this score can and cannot tell you",text:["A diet-quality score summarizes eating-pattern inputs into a single number. That is useful for tracking broad habits, but it is not a laboratory test, nutrient-deficiency diagnosis or direct implementation of the USDA Healthy Eating Index unless every component and scoring rule matches that validated instrument.","Read the component feedback alongside the total. Two people can receive similar totals for very different diets, so the actionable information is which food groups, processing patterns or nutrient-related habits are pulling the score down."]},{heading:"Vegetables, fruit and dietary variety",text:["Vegetables and fruit contribute fiber, potassium, folate, vitamin C and a wide range of phytochemicals. Variety matters because leafy greens, legumes, orange vegetables, berries and citrus do not provide identical nutrient profiles.","A practical improvement is to count servings across the week rather than trying to make one meal perfect. Frozen and unsweetened canned produce can contribute meaningfully when fresh options are inconvenient."]},{heading:"Whole grains and fiber",text:["Whole grains retain more bran and germ than refined grains and generally provide more fiber and micronutrients. Fiber also comes from beans, lentils, vegetables, fruit, nuts and seeds, so grain choice is only one part of the pattern.","When comparing packaged foods, inspect the ingredient list and fiber per serving instead of relying on brown color or marketing terms such as multigrain. A product can contain several grains while still being predominantly refined flour."]},{heading:"Protein quality and distribution",text:["Diet quality is influenced by protein source as well as quantity. Fish, legumes, nuts, seeds, eggs, dairy and minimally processed lean meats can fit healthy patterns, while frequent processed meat intake deserves separate attention.","Plant proteins can meet needs when total protein and essential amino acids are adequate. People with high training loads, older adults or restrictive diets may need more deliberate protein planning than a general score captures."]},{heading:"Ultra-processed foods and added sugar",text:["Ultra-processed foods are not defined simply by being packaged. The NOVA framework focuses on industrial formulations and ingredients, while nutrition labels separately reveal added sugars, sodium, saturated fat and fiber. Both perspectives can be useful.","Instead of treating every processed item as equally harmful, identify the foods contributing the most calories with little satiety or nutritional value: sugary drinks, confectionery, many snack foods and some refined convenience meals are common targets."]},{heading:"Fat quality, sodium and cardiometabolic context",text:["Replacing some saturated fat with unsaturated fats from olive oil, nuts, seeds, avocado and fish can improve the overall fat profile. Sodium sensitivity varies, but high sodium intake is particularly relevant when blood pressure is elevated.","The score cannot see blood pressure, LDL cholesterol, triglycerides, glucose or kidney function. Those measurements can change how dietary priorities should be ranked."]},{heading:"Mediterranean and DASH patterns",text:["Mediterranean-style and DASH-style eating patterns are useful examples because they emphasize combinations of foods rather than isolated superfoods. Both favor vegetables, fruit, whole grains and minimally processed foods, with DASH placing particular emphasis on blood-pressure-friendly nutrient patterns.","You do not need to reproduce a named diet perfectly. The transferable lesson is pattern consistency: improving several recurring meals has more impact than occasionally eating one exceptionally healthy meal."]},{heading:"Use the score for trend tracking",text:["Repeat the assessment under similar assumptions, perhaps monthly rather than daily. Focus on one or two low-scoring components at a time and choose measurable changes, such as adding legumes twice weekly or replacing a sugary drink on workdays.","People with eating disorders, significant gastrointestinal disease, kidney disease, pregnancy or medically prescribed diets should not optimize a generic score at the expense of individualized nutrition guidance."]},]},
'lease-vs-buy-calculator':{title:'Lease vs Buy Calculator',sections:[
{heading:'What this comparison actually measures',text:['A lease-versus-buy decision is not just a comparison between a lease payment and a loan EMI. This calculator models the cash committed to each path over the periods entered, then recognizes that a purchased vehicle or asset can still have resale value. The useful question is therefore how much economic cost remains after financing, ownership expenses and residual value are considered.','The current tool accepts vehicle or asset price, down payment, loan interest rate and tenure, expected resale value, monthly lease payment, lease duration, and differences in insurance and maintenance. Those inputs describe two different cash-flow structures, so compare them over a horizon that makes sense for the decision rather than assuming the lowest monthly payment is automatically cheapest.']},
{heading:'Buying: price, down payment and financed principal',text:["For the purchase path, the down payment reduces the amount financed but is still part of the buyer's economic outlay. A larger down payment normally lowers the loan principal and interest expense, yet it also ties up more cash on day one. When comparing alternatives, remember that down payment is not a discount on the vehicle; it is simply an earlier payment toward ownership.",'If the asset price is 1,500,000 and the down payment is 300,000, the financed principal begins at 1,200,000 before any fees that the calculator does not model. Real auto transactions may also include registration, taxes, dealer charges, loan origination fees or accessories. Add those separately when they are material because they can change the purchase side substantially.']},
{heading:'How the loan rate and tenure change ownership cost',text:['A loan converts the financed principal into periodic payments containing both principal and interest. Higher rates increase financing cost; longer terms usually reduce the required monthly payment but keep debt outstanding longer and can increase total interest. This is why a five-year loan at nine percent cannot be judged only by its EMI relative to a three-year lease payment.',"A longer loan can also create a period of negative equity when the outstanding balance exceeds resale value. The calculator's resale input helps capture end-value economics, but it does not display the month-by-month loan balance. If you may sell early, compare the expected sale price with the remaining payoff amount at that specific date."]},
{heading:'Residual value is central to the buy case',text:["Ownership leaves an asset that may be sold or retained. The resale or residual value is therefore an offset to ownership cost, not a cash expense. Underestimating it makes buying look worse; overestimating it makes buying look artificially attractive. Use a value appropriate to the vehicle's age, mileage, condition and local market at the comparison date.","Depreciation is often steepest early in a vehicle's life. A three-year-old vehicle can retain a very different percentage of original price than a seven-year-old one. If the lease duration and ownership horizon differ, be explicit about what date the residual value represents. A residual estimate for year five should not be subtracted from costs accumulated for only three years."]},
{heading:'Understand what a lease payment contains',text:["A lease payment is payment for the right to use an asset for a defined period rather than payment toward ownership equity. The quoted monthly amount may reflect depreciation, financing or rent charges, taxes and the contract's residual assumption. The calculator uses the monthly lease payment you enter, so the quality of the comparison depends on whether that number represents the real all-in recurring payment.",'Many leases also have an acquisition fee, disposition fee, security deposit, registration costs, upfront taxes, mileage limits and excess-wear charges. Those are not represented by a single monthly payment unless you deliberately amortize them into the entered figure. For a serious decision, add all unavoidable lease cash flows before comparing with purchase economics.']},
{heading:'Insurance and maintenance differences',text:['The calculator includes insurance and maintenance differences because the two paths can create different running costs. A leased vehicle may require specified coverage levels, while an owned vehicle may have different insurance choices after a loan is repaid. Maintenance can also differ if a lease keeps the vehicle inside a warranty period while long-term ownership extends into higher-repair years.','Enter differences rather than assuming these costs cancel. If leasing costs 2,000 more per month for insurance but saves 1,500 per month in expected maintenance, the net operating difference is only 500 per month before other expenses. Fuel, parking and tolls usually do cancel when the same vehicle and driving pattern are compared, but they should be included when the alternatives themselves differ.']},
{heading:'Match the comparison horizon',text:["A fair comparison uses a common decision horizon. Comparing three years of lease payments with five years of purchase payments without recognizing the buyer's remaining asset and loan position can produce a misleading conclusion. Decide whether you are asking, for example, 'Which path costs less over three years?' or 'Which strategy costs less over six years if I lease twice versus buy once?'","For repeated leasing, model the next lease as well rather than assuming the first contract's terms continue forever. For buying, include the expected resale value at the same terminal date. The more the horizons differ, the more important it becomes to construct a separate cash-flow schedule outside the simplified calculator."]},
{heading:'Mileage, wear and flexibility can overturn the arithmetic',text:['Lease contracts commonly cap annual mileage and charge for excess miles or abnormal wear. A driver whose mileage is uncertain can face a large terminal charge that is absent from the displayed monthly payment. Buying generally offers more freedom to drive, modify, keep or sell the vehicle, although ownership exposes you directly to resale-price risk.','Leasing can provide predictable replacement cycles and may reduce exposure to out-of-warranty repairs. Buying can be economically powerful when the vehicle is kept for years after the loan is repaid. Those differences are not soft details: they determine which cash flows should be modeled and can outweigh a modest advantage shown by the calculator.']},
{heading:'Opportunity cost of cash',text:['A down payment has an opportunity cost because cash committed to the purchase cannot simultaneously remain in savings, reduce higher-rate debt or be invested. Conversely, investing the difference is not guaranteed to earn a particular return. If opportunity cost matters, compare realistic after-tax returns with the borrowing rate and preserve an emergency-cash buffer.','Do not automatically assume that a zero-down purchase is superior because cash stays invested. More borrowing raises interest expense and leverage. Likewise, do not assume a large down payment is always best: if it drains liquidity, the household may be forced to borrow elsewhere at a higher rate when an unexpected expense occurs.']},
{heading:'Worked interpretation',text:["Suppose the vehicle costs 1,500,000, you put 300,000 down, finance the balance for five years at nine percent, and expect the vehicle to be worth 600,000 later. Compare that ownership path with a 25,000 monthly lease for three years, then incorporate the entered insurance and maintenance differences. The calculator's result should be read as a modeled cost comparison under those exact assumptions.",'Now reduce the resale estimate, raise the loan rate, or add a realistic lease acquisition and mileage charge. If the preferred option changes easily, the decision is sensitive rather than decisive. That is useful information: it tells you to negotiate the variables that matter most instead of focusing on cosmetic differences in monthly payment.']},
{heading:'Important omissions and limitations',text:['This calculator is a planning model, not a lease contract analyzer. It does not automatically model sales tax rules, GST/VAT treatment, business deductions, depreciation tax benefits, lease money factors, security deposits, mileage penalties, early-termination charges, registration, transaction fees, or a detailed amortization schedule for every possible jurisdiction.',"For business assets, tax treatment can be materially different from personal use and may depend on business-use percentage, entity type and local law. For consumer vehicles, obtain the actual out-the-door purchase price and the lease's total amount due at signing plus total scheduled payments. Replace advertised figures with contract figures before making a high-value decision."]},
{heading:'How to use the result well',text:['Use the calculator first to establish a base case, then vary only the inputs that are genuinely uncertain: resale value, holding period, lease payment, financing rate and maintenance difference. Keep the comparison horizon consistent. A result that remains favorable under conservative assumptions is stronger than one that depends on a perfect resale price or unrealistically cheap future lease.',"The final choice can legitimately differ from the cheapest modeled option. Flexibility, predictable replacement, ownership preference, annual mileage and liquidity all have value. The calculator's job is to make the financial tradeoff visible so that those nonfinancial preferences are not accidentally confused with cost savings."]},
]},
"auto-loan-calculator":{title:"Auto Loan Calculator",sections:[{heading:"From vehicle price to amount financed",text:["An auto loan starts with the out-the-door transaction, not just the sticker price. Purchase price can be increased by sales tax and fees, then reduced by cash down payment, rebates and net trade-in value. If an old loan has negative equity, that shortage may be rolled into the new amount financed.","Always reconcile the calculator's financed amount with the buyer's order. A low advertised vehicle price can be offset by add-ons, documentation charges or negative equity."]},{heading:"How the monthly payment is calculated",text:["For a standard amortizing loan, the payment depends on principal, periodic interest rate and number of monthly payments. Each early payment contains more interest because the outstanding balance is larger; later payments shift toward principal.","APR and term interact strongly. Extending a loan from 48 to 72 months can reduce the payment while increasing total interest and keeping the balance high for longer."]},{heading:"APR versus interest rate and dealer offers",text:["APR is intended to reflect borrowing cost more broadly than a simple note rate when required finance charges are included. Dealer advertising may emphasize a promotional rate while the transaction price, rebate eligibility or add-ons change elsewhere.","Compare financing and vehicle negotiation separately. Ask for the out-the-door price before discussing monthly-payment targets so term stretching does not hide a higher purchase price."]},{heading:"Down payment and trade-in equity",text:["A larger down payment reduces principal and interest and can reduce the chance of owing more than the car is worth. Trade-in equity functions similarly, but trade value and remaining payoff must be separated: a $15,000 trade with a $12,000 payoff contributes only $3,000 of equity.","If the payoff exceeds trade value, the negative equity is effectively additional borrowing. Rolling it forward can create a loan balance far above the replacement vehicle's market value."]},{heading:"Depreciation and being underwater",text:["Vehicles typically depreciate faster in the early ownership years. Long loan terms, small down payments and rolled negative equity can make the loan balance fall more slowly than the vehicle's value.","Being underwater matters if the car is totaled, stolen or sold early. Gap coverage may address certain insured shortfalls, but terms and exclusions vary and it does not make an overpriced loan economical."]},{heading:"Taxes, fees and add-ons",text:["Sales tax treatment varies by jurisdiction and may interact with trade-in credits. Registration, title, documentation charges and dealer-installed products can also change the financed balance.","Extended warranties, service contracts and protection products should be evaluated individually. Financing a $2,000 add-on means paying interest on it as well as the purchase price."]},{heading:"Worked term comparison",text:["Consider $28,000 financed at 7% APR. A shorter term produces a higher monthly payment but principal falls faster and total interest is lower. A longer term creates payment relief at the cost of more interest and a longer period of negative-equity risk.","Run the calculator at 48, 60 and 72 months with the same principal and APR. The comparison makes the price of the lower monthly payment explicit."]},{heading:"Prepayment and refinancing",text:["Many auto loans allow extra principal payments without penalty, but verify the contract and how the servicer applies extra money. Paying principal early can reduce future interest on a simple-interest loan.","Refinancing can help when credit improves or market rates fall, but compare remaining interest, new term and fees. Resetting a nearly paid-down loan into a long new term can lower the payment while delaying debt freedom."]},]},
'exercise-addiction-calculator':{title:'Exercise Addiction Calculator',sections:[
{heading:'What the score is designed to flag',text:['This tool screens for patterns that can make exercise rigid, compulsive or harmful. It uses workout frequency together with guilt on rest days, anxiety when a workout is missed, exercising despite injury, social sacrifice, identity tied to exercise, exercising for control and inability to reduce. Those behavioral signals matter more than simply asking whether someone trains often.','The displayed risk percentage is an internal model score, not a clinical probability that a person has a psychiatric diagnosis. High-volume training can be healthy in an athlete with recovery, flexibility and medical support, while a lower training volume can still be problematic when exercise is driven by compulsion, fear or self-punishment.']},
{heading:'Frequency alone does not define addiction',text:['Workouts per week provides context but cannot distinguish disciplined training from compulsive exercise by itself. Competitive athletes may train more than once per day during some phases. The important distinction is whether training remains adaptable to injury, illness, recovery needs and ordinary life obligations.','If reducing one session creates disproportionate distress or feels impossible even when rest is clearly needed, that behavioral response deserves more attention than the raw weekly count. Use frequency together with the psychological and functional inputs rather than treating a threshold as diagnostic.']},
{heading:'Rest-day guilt and missed-workout anxiety',text:['Guilt on rest days can signal that recovery is being interpreted as failure rather than as part of training. Anxiety when a session is missed can similarly show that exercise has become a rule that must be obeyed. Occasional disappointment is different from persistent distress that changes mood, eating behavior or social decisions.','When entering these ratings, think about typical weeks rather than the most motivated or least motivated day. A score is more informative when it reflects the recurring pattern over several weeks.']},
{heading:'Training through injury is a major warning sign',text:['The exercise-over-injury input captures a concrete harm signal. Pain and injury sometimes require modified activity, rehabilitation or rest. Repeatedly overriding those limits to satisfy an exercise rule can prolong injury and suggests loss of behavioral flexibility.','This tool cannot determine whether pain is safe to train through. Acute injury, chest pain, fainting, severe shortness of breath or other concerning symptoms require appropriate medical assessment rather than a calculator score.']},
{heading:'Social sacrifice and functional impairment',text:['Exercise becomes more concerning when it repeatedly displaces relationships, work, education or necessary responsibilities. Choosing a workout over one social event is not automatically harmful; the pattern matters. The calculator asks about sacrifice because impairment is more informative than enthusiasm alone.','Ask whether exercise scheduling has become so rigid that ordinary changes cause conflict, secrecy or isolation. If the answer is yes, the issue may be the relationship with exercise rather than the training plan itself.']},
{heading:'Identity tied to exercise',text:['Exercise can be an important and positive part of identity. Risk rises when self-worth becomes narrowly dependent on completing workouts, achieving a body ideal or maintaining performance. Injury or a forced break can then produce unusually strong shame, anxiety or loss of identity.','A resilient athletic identity includes other roles and values. If the calculator score is elevated largely because identity and control ratings are high, broadening sources of self-worth may be more relevant than merely reducing a numerical workout target.']},
{heading:'Exercise for control and eating-disorder overlap',text:['Some people use exercise to regulate mood or create structure, which can be healthy. Concern increases when exercise is used to compensate for eating, earn food, prevent feared weight change or manage distress in a rigid way. Compulsive exercise can overlap with eating disorders even when body weight appears normal.','The calculator does not assess food restriction, bingeing, purging, body-image disturbance, menstrual changes or other eating-disorder features comprehensively. If those are present, a low or moderate exercise score should not be used as reassurance.']},
{heading:'Unable to reduce is different from unwilling to reduce',text:['A person may prefer not to reduce training because it supports a goal. The more concerning pattern is repeated unsuccessful attempts to cut back despite recognizing harm or wanting change. That loss-of-control element is why the calculator includes an unable-to-reduce switch.','Try interpreting the question behaviorally: when illness, injury, travel or a planned recovery week calls for less training, can the plan change without severe distress or compensatory behavior? Flexibility is a useful marker of a healthier relationship with exercise.']},
{heading:'Recovery signals the calculator does not fully capture',text:['Persistent fatigue, declining performance, sleep disruption, recurrent injury, irritability, loss of menstrual function, reduced libido and frequent illness can indicate inadequate recovery or low energy availability. These can occur with excessive training even without exercise addiction, and they deserve attention in their own right.','The tool also does not calculate training load, energy availability, overtraining syndrome or RED-S. Use appropriate sports-medicine assessment when the concern is physiological under-recovery rather than primarily compulsive behavior.']},
{heading:'How to respond to an elevated score',text:['An elevated result is a prompt to examine the pattern, not a label. Consider discussing the behavior with a clinician, sports psychologist, therapist, dietitian or other professional familiar with compulsive exercise and eating disorders, especially when injury, food compensation, severe anxiety or functional impairment is present.','Short-term experiments can also reveal rigidity: schedule genuine recovery, replace a session with a non-exercise activity, and observe the emotional response. Do not use such experiments to push through a medical problem; the goal is to understand flexibility, not to prove toughness.']},
{heading:'Track change rather than chasing a perfect score',text:['If the tool is repeated, use similar time frames and answer based on actual behavior. A lower score is meaningful only if it reflects healthier flexibility and recovery rather than concealment or a temporary forced break. Pair the score with notes about injury, mood, sleep, relationships and eating patterns.','The healthiest outcome is not necessarily the fewest workouts. It is a sustainable pattern in which exercise supports health and performance without dominating self-worth, overriding injury or repeatedly displacing the rest of life.']},
]},
"nutrition-timing-calculator":{title:"Nutrition Timing Calculator",sections:[{heading:"What the schedule is calculating",text:["The tool takes wake time, exercise time, bedtime, a goal, intermittent-fasting status and fasting-window length. Without fasting it starts the eating window one hour after waking and ends it one hour before bed. With fasting enabled, it derives an eating-window start from wake time plus 24 minus fasting hours, then creates an end based on the resulting eating-window duration.","It also schedules a pre-workout meal 1.5 hours before exercise, a post-workout meal 30 minutes after exercise and a last meal no later than two hours before bed or the eating-window end. These are planning rules built into the page, not universal physiological deadlines."]},{heading:"Daily protein and energy matter more than perfect timing",text:["For muscle gain, recovery and body-composition goals, total daily energy and protein intake usually matter more than hitting a minute-perfect anabolic window. Timing can help distribute nutrients around training, but an otherwise inadequate diet is not rescued by a precisely timed shake.","A practical approach is to establish an appropriate daily intake first, then distribute meals in a way that supports training, hunger control, sleep and adherence. The calculator's clock times are best treated as anchors that can be moved around work, family and gastrointestinal comfort."]},{heading:"Pre-workout nutrition",text:["The model places a meal 90 minutes before exercise. In practice, meal size and composition determine how much lead time is comfortable. A larger mixed meal may need several hours, while a small carbohydrate snack can be tolerated closer to training. Endurance sessions and high-volume resistance training may benefit more from pre-exercise carbohydrate than a short easy session.","The page's fat-loss tip suggests skipping pre-workout carbohydrate for fasted morning cardio to maximize fat oxidation. Greater fat oxidation during a session does not automatically mean greater long-term fat loss; energy balance and adherence remain central. People prone to dizziness, hypoglycemia or poor fasted performance should not force a fast simply because the tool displays that tip."]},{heading:"Post-workout protein and carbohydrate",text:["For muscle gain the tool recommends 25–40 g protein within an hour after training. Protein near training is useful, but the recovery opportunity is broader than a narrow one-hour deadline, especially when a protein-containing meal was eaten beforehand. Spreading high-quality protein across several meals can support muscle-protein synthesis over the day.","Carbohydrate replacement becomes more time-sensitive when another demanding session is coming soon or glycogen depletion is substantial. Recreational trainees with a full day before the next workout generally have more flexibility."]},{heading:"Intermittent fasting windows",text:["If intermittent fasting is enabled, the fasting-window input determines the modeled eating duration. A 16-hour fast implies an eight-hour eating window. Clock arithmetic around midnight can be unintuitive, so verify that the displayed start and end actually match the schedule you intend.","Fasting is a meal-pattern strategy, not a requirement for fat loss or longevity. It can help some people control intake and simplify eating, while others experience excessive hunger, poor training, sleep disruption or difficulty meeting nutrient needs. Pregnancy, eating-disorder history, diabetes medications and other medical circumstances require individualized advice."]},{heading:"Circadian timing and the last meal",text:["The calculator labels 10 AM–2 PM exercise as 'circadian-optimal' and 4–7 PM as favorable for performance, while suggesting an earlier eating pattern for longevity. Human performance and glucose handling do show daily rhythms, but individual chronotype, work schedule, sleep and training consistency matter. The code's labels are simplified and should not be treated as a universal biological prescription.","The last-meal rule aims for at least two hours before bedtime. Some people sleep better without a large late meal, but athletes or people with high energy needs may still need evening nutrition. Meal size, reflux symptoms and total intake are more informative than a rigid cutoff alone."]},{heading:"Worked schedule example",text:["For someone waking at 7 AM, training at 5 PM and sleeping at 11 PM without fasting, the tool starts eating around 8 AM, suggests a pre-workout meal around 3 PM, a post-workout meal around 5:30 PM and a last meal by roughly 9 PM. That schedule is easy to understand because all events occur on the same day.","With a 16-hour fast, verify the generated eating window carefully and decide whether it supports the training session. If the calculated window makes pre- or post-workout nutrition impractical, adherence and performance may justify changing the fasting schedule rather than forcing training around an arbitrary window."]},{heading:"Goal-specific interpretation",text:["For muscle gain, prioritize adequate calories, protein and progressive training. For performance, carbohydrate availability and hydration may deserve more attention around demanding sessions. For fat loss, a sustainable calorie deficit and protein intake matter more than whether food is eaten at a particular clock time. For longevity, diet quality, energy balance, activity, sleep and cardiometabolic risk factors outweigh any single meal-timing rule.","Use the calculator as a schedule builder. Adjust the proposed times for shift work, medications, gastrointestinal tolerance, cultural eating patterns and training demands. A useful nutrition plan is one that meets nutrient needs and can be followed consistently, not simply one that matches every displayed clock time."]},]},
"waist-hip-ratio-calculator":{title:"Waist-to-Hip Ratio Calculator",sections:[{heading:"The WHR formula",text:["Waist-to-hip ratio is waist circumference divided by hip circumference. A waist of 85 cm and hips of 100 cm gives a WHR of 0.85. Because it is a ratio, centimeters and inches produce the same answer as long as both measurements use the same unit. The calculator rounds the ratio to two decimals.","WHR describes body-fat distribution rather than total body mass. A higher ratio generally reflects more abdominal concentration relative to the hips, which is why it is often discussed alongside cardiometabolic risk. It should complement, not replace, BMI, waist circumference and clinical risk factors."]},{heading:"Measure waist and hips consistently",text:["Measurement error can move someone across a category. Use a flexible, non-stretch tape, stand relaxed, keep the tape horizontal and avoid compressing the skin. Waist protocols differ by organization—some use the midpoint between the lowest rib and iliac crest, others use another landmark—so use the protocol that matches the reference thresholds and keep it consistent for repeat measurements.","Hip circumference is usually taken around the widest portion of the buttocks. Measure more than once if readings differ, and avoid comparing a morning measurement with a post-meal measurement taken under very different conditions when tracking small changes."]},{heading:"How this calculator classifies risk",text:["The site's model uses sex-specific cutoffs. For men it sets a low reference at 0.85 and a high threshold at 0.90; for women those values are 0.80 and 0.85. It then assigns low, low-moderate, moderate or high categories. These are simplified categories built into this calculator and should not be interpreted as an individual's exact probability of diabetes, heart attack or stroke.","Age is collected by the page but the current calculation does not use age to change the ratio or thresholds. That is important when interpreting the output: entering age 25 versus 65 with identical waist, hip and sex values produces the same WHR classification even though absolute cardiovascular risk can differ greatly with age."]},{heading:"Waist circumference matters independently",text:["The code separately flags a metabolic-syndrome indicator when waist exceeds 102 cm for men or 88 cm for women. It also labels values above those thresholds as comparable to an obese-BMI level of cardiometabolic concern. This means two people with the same WHR can receive different contextual messages if their absolute waist sizes differ.","Absolute cutoffs are not universally appropriate for every population. Some clinical guidelines use lower waist thresholds for certain ethnic groups. If you are using WHR for health decisions, compare the site's thresholds with guidance appropriate to your population and clinician's assessment."]},{heading:"Ideal waist and waist-to-lose output",text:["The calculator estimates an 'ideal waist' as 85% of hip circumference for men and 80% for women, then subtracts that from the entered waist to display 'waist to lose.' This is a mathematical target derived from the model's reference ratio, not a personalized prescription for how many centimeters a person medically needs to lose.","Hip circumference can itself change with weight loss, muscle gain or aging, so holding hips fixed while targeting the calculated waist is an approximation. Focus on sustainable health behaviors and longitudinal risk markers rather than chasing a single tape-measure number."]},{heading:"Worked examples",text:["A woman with an 80 cm waist and 100 cm hips has WHR 0.80, around the calculator's low reference. If waist rises to 90 cm while hips remain 100 cm, WHR becomes 0.90 and crosses the site's high-risk threshold. The ratio changed because abdominal circumference changed relative to hip size.","A man with a 90 cm waist and 105 cm hips has WHR about 0.86. Another man with a 110 cm waist and 128 cm hips also has a ratio near 0.86, yet the second person's absolute waist exceeds the calculator's 102 cm abdominal-obesity marker. This illustrates why ratio and waist circumference should be read together."]},{heading:"WHR versus BMI and waist-to-height ratio",text:["BMI summarizes weight relative to height but says little about where mass is carried. WHR compares abdominal and gluteal circumference but ignores height and total weight. Waist-to-height ratio compares waist with stature and is another simple central-adiposity measure. Each captures a different aspect of body size.","When measures disagree, do not assume one automatically wins. Athletic build, pregnancy, body shape, age and measurement technique can affect interpretation. Clinical risk assessment also incorporates blood pressure, glucose, lipids, smoking and family history."]},{heading:"Use WHR as a trend, not a verdict",text:["For self-monitoring, repeat measurements under similar conditions and look for sustained changes rather than reacting to a one-centimeter fluctuation. Record waist and hip values, not only the rounded ratio, because rounding can hide small trends.","A high WHR can be a reason to discuss cardiometabolic risk and lifestyle factors, but it does not diagnose metabolic syndrome or predict an event with certainty. A low WHR likewise does not cancel other risk factors. The calculator is most useful as one screening perspective within a broader health picture."]},]},
}
export function CalculatorBatch48DeepDive({slug}:{slug:string}){const g=guides[slug];if(!g)return null;return <section className="mx-auto max-w-5xl px-4 py-10"><div className="rounded-2xl border border-gray-200 bg-white p-6 md:p-8"><h2 className="text-2xl md:text-3xl font-bold text-gray-900">{g.title}: Detailed Guide</h2><p className="mt-3 text-gray-700 leading-7">A detailed guide to the inputs, formula logic, scenarios, timing, costs, thresholds, limitations and practical use of this specific tool.</p><div className="mt-8 space-y-8">{g.sections.map((s,i)=><article key={i}><h3 className="text-xl font-semibold text-gray-900">{s.heading}</h3>{s.text.map((p,j)=><p key={j} className="mt-3 text-gray-700 leading-7">{p}</p>)}</article>)}</div></div></section>}